package main

import (
	"crypto/subtle"
	"crypto/tls"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
	"sync"
	"unicode"
)

type ModelRegistry struct {
	mu       sync.RWMutex
	models   map[string]*ModelEndpoint
	allowACE bool
}

type ModelEndpoint struct {
	Name     string `json:"name"`
	Backend  string `json:"backend"`
	APIKey   string `json:"api_key"`
	IsPublic bool   `json:"is_public"`
}

type InferenceRequest struct {
	ModelName string                 `json:"model_name"`
	Inputs    map[string]interface{} `json:"inputs"`
}

var registry = &ModelRegistry{
	models:   make(map[string]*ModelEndpoint),
	allowACE: false,
}

const adminAuthToken = "Bearer admin-token-xyz"

func init() {
	registry.models["gpt-4"] = &ModelEndpoint{
		Name: "gpt-4", Backend: "http://internal-gpu-cluster:8080/v1/inference",
		APIKey: "sk-internal-prod-key-do-not-expose", IsPublic: true,
	}
	registry.models["embeddings-v2"] = &ModelEndpoint{
		Name: "embeddings-v2", Backend: "http://internal-gpu-cluster:8080/v2/embed",
		APIKey: "sk-embed-secret-key", IsPublic: true,
	}
	registry.models["admin-finetune"] = &ModelEndpoint{
		Name: "admin-finetune", Backend: "http://internal-gpu-cluster:8080/admin/finetune",
		APIKey: "sk-admin-master-key", IsPublic: false,
	}
}

// normalizeModelName applies strict ASCII-only normalization to prevent homograph attacks
func normalizeModelName(name string) (string, error) {
	var normalized strings.Builder
	for _, r := range name {
		if r > 0x007F {
			return "", fmt.Errorf("non-ASCII character U+%04X rejected", r)
		}
		if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '-' || r == '_' {
			normalized.WriteRune(r)
		}
	}
	return normalized.String(), nil
}

// isConfusable checks if a rune could be a homograph of an ASCII character
func isConfusable(r rune) bool {
	// Check for characters outside Basic Latin that look like ASCII
	if r > 0x007F && unicode.IsLetter(r) {
		return true
	}
	return false
}

// validateModelAccess checks if the model can be accessed
func validateModelAccess(modelName string, authToken string) (*ModelEndpoint, error) {
	registry.mu.RLock()
	defer registry.mu.RUnlock()

	// First normalize the input - reject non-ASCII
	normalized, err := normalizeModelName(modelName)
	if err != nil {
		return nil, fmt.Errorf("invalid model name: %v", err)
	}

	// Look up the model
	endpoint, exists := registry.models[normalized]
	if !exists {
		return nil, fmt.Errorf("model %q not found", normalized)
	}

	// Check access control (constant-time comparison to avoid timing attacks)
	if !endpoint.IsPublic && subtle.ConstantTimeCompare([]byte(authToken), []byte(adminAuthToken)) != 1 {
		return nil, fmt.Errorf("access denied to model %q", normalized)
	}

	return endpoint, nil
}

// proxyToBackend forwards the request to the ML backend
func proxyToBackend(w http.ResponseWriter, r *http.Request, endpoint *ModelEndpoint) {
	backendURL, err := url.Parse(endpoint.Backend)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	proxy := &httputil.ReverseProxy{
		Director: func(req *http.Request) {
			req.URL = backendURL
			req.Host = backendURL.Host
			req.Header.Set("X-Internal-API-Key", endpoint.APIKey)
			req.Header.Set("X-Model-Name", endpoint.Name)
		},
		Transport: &http.Transport{
			TLSClientConfig: &tls.Config{InsecureSkipVerify: false},
		},
	}
	proxy.ServeHTTP(w, r)
}

func inferenceHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req InferenceRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	authToken := r.Header.Get("Authorization")

	endpoint, err := validateModelAccess(req.ModelName, authToken)
	if err != nil {
		http.Error(w, err.Error(), http.StatusForbidden)
		return
	}

	proxyToBackend(w, r, endpoint)
}

func modelListHandler(w http.ResponseWriter, r *http.Request) {
	registry.mu.RLock()
	defer registry.mu.RUnlock()

	var publicModels []string
	for name, ep := range registry.models {
		if ep.IsPublic {
			publicModels = append(publicModels, name)
		}
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{"models": publicModels})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/v1/inference", inferenceHandler)
	mux.HandleFunc("/v1/models", modelListHandler)

	log.Println("ML Inference Gateway starting on :9090")
	if err := http.ListenAndServe(":9090", mux); err != nil {
		log.Fatal(err)
	}
}
